create extension if not exists pgcrypto;
create type public.teamtrack_role as enum ('manager','team_lead','employee');
create type public.attendance_event_type as enum ('login','break_in','break_out','lunch_in','lunch_out','logout');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.teamtrack_role not null default 'employee',team_id uuid,active boolean not null default true,created_at timestamptz not null default now());
create table public.shifts(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.profiles(id),shift_date date not null,start_time time not null,end_time time not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(employee_id,shift_date));
create table public.shift_acknowledgements(id uuid primary key default gen_random_uuid(),shift_id uuid not null references public.shifts(id) on delete cascade,employee_id uuid not null references public.profiles(id),acknowledged boolean not null default false,acknowledged_at timestamptz not null default now(),unique(shift_id,employee_id));
create table public.attendance_events(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.profiles(id),event_type public.attendance_event_type not null,created_at timestamptz not null default now(),client_recorded_at timestamptz,latitude double precision,longitude double precision,photo_path text,notes text);
alter table public.profiles enable row level security;
alter table public.shifts enable row level security;
alter table public.shift_acknowledgements enable row level security;
alter table public.attendance_events enable row level security;
create function public.current_role() returns public.teamtrack_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create policy "profiles read self or leaders" on public.profiles for select to authenticated using(id=auth.uid() or public.current_role() in ('manager','team_lead'));
create policy "manager manages profiles" on public.profiles for all to authenticated using(public.current_role()='manager') with check(public.current_role()='manager');
create policy "read own or leader shifts" on public.shifts for select to authenticated using(employee_id=auth.uid() or public.current_role() in ('manager','team_lead'));
create policy "manager manages shifts" on public.shifts for all to authenticated using(public.current_role()='manager') with check(public.current_role()='manager');
create policy "ack own shift" on public.shift_acknowledgements for insert to authenticated with check(employee_id=auth.uid());
create policy "read acknowledgements" on public.shift_acknowledgements for select to authenticated using(employee_id=auth.uid() or public.current_role() in ('manager','team_lead'));
create policy "insert own attendance" on public.attendance_events for insert to authenticated with check(employee_id=auth.uid());
create policy "read attendance" on public.attendance_events for select to authenticated using(employee_id=auth.uid() or public.current_role() in ('manager','team_lead'));
insert into storage.buckets(id,name,public) values('attendance-photos','attendance-photos',false) on conflict(id) do nothing;
create policy "upload own photos" on storage.objects for insert to authenticated with check(bucket_id='attendance-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "read attendance photos" on storage.objects for select to authenticated using(bucket_id='attendance-photos');
